static void render(FILE *out, const char *tpl, const struct page *m) {
    const char *p = tpl;
    while (*p) {
        const char *h = strstr(p, "{{");
        if (!h) { fputs(p, out); break; }
        fwrite(p, 1, (size_t)(h - p), out);
        if (!strncmp(h, "{{title}}", 9))     fprintf(out, "%s", escape_html(m->title));
        else if (!strncmp(h, "{{body}}", 8)) fputs(escape_html(m->body), out);
        p = strchr(h, '}') + 2;
    }
}
